<?php
namespace Tests\Feature;
use Tests\TestCase;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Facades\{Http,Storage,DB};
use App\Models\{User,MarketingChannelConnection};
class MarketingVideoPublishingTest extends TestCase {
 use RefreshDatabase;
 private function fixture(string $platform='youtube'):array{
  $u=User::factory()->create(['is_admin'=>true,'is_super_admin'=>true]);$this->actingAs($u);config(['marketing.post_queue_enabled'=>false,'marketing.post_scheduling_enabled'=>false,'marketing.execution_enabled'=>false,'marketing.social_publishing_enabled'=>true,'marketing.external_video_publishing_enabled'=>true,'services.youtube.client_id'=>'yt','services.tiktok.client_id'=>'tk']);Http::preventStrayRequests();Storage::fake('local');$id=(string)\Illuminate\Support\Str::uuid();Storage::disk('local')->put('test.mp4','test-video-bytes');DB::table('marketing_post_media')->insert(['id'=>$id,'user_id'=>$u->id,'title'=>'Existing test video','path'=>'test.mp4','sha256'=>hash('sha256','test-video-bytes'),'bytes'=>16,'seconds'=>15,'created_at'=>now(),'updated_at'=>now()]);
  $a=MarketingChannelConnection::create(['merchant_key'=>app(\App\Services\Marketing\MarketingChannels::class)->merchant(),'platform'=>$platform,'provider_account_id'=>$platform==='youtube'?'UC-test':'tk-user','app_id'=>$platform==='youtube'?'yt':'tk','name'=>'Test creator','access_token'=>'PRIVATE-TOKEN','permissions'=>$platform==='youtube'?['https://www.googleapis.com/auth/youtube.readonly','https://www.googleapis.com/auth/youtube.upload']:['user.info.basic','video.publish'],'authorized_by'=>$u->id,'state'=>'connected','expires_at'=>now()->addHour()]);
  $opts=$platform==='youtube'?['title'=>'Private publishing test','privacy'=>'private','made_for_kids'=>false,'synthetic'=>false]:['privacy'=>'SELF_ONLY','allow_comment'=>false,'allow_duet'=>false,'allow_stitch'=>false,'commercial'=>false,'your_brand'=>false,'branded'=>false,'terms'=>true];
  return ['id'=>(string)\Illuminate\Support\Str::uuid(),'version'=>0,'title'=>'Video test','copy'=>'JW Marketing Studio test.','targets'=>[$a->id],'copies'=>[],'asset'=>'upload:'.$id,'type'=>'Reel','tz'=>'Asia/Kuala_Lumpur','options'=>[$a->id=>$opts]];
 }
 public function test_youtube_uses_persisted_session_and_only_one_upload(){ $p=$this->fixture();Http::fake(function($r){if($r->method()==='POST')return Http::response([],200,['Location'=>'https://www.googleapis.com/upload/youtube/v3/videos?upload_id=fixture']);if($r->method()==='PUT')return Http::response(['id'=>'video-1','status'=>['uploadStatus'=>'processed','privacyStatus'=>'private']]);return Http::response(['items'=>[['id'=>'video-1','status'=>['uploadStatus'=>'processed','privacyStatus'=>'private']]]]);});$this->postJson('/admin/marketing/posts/data/publish',$p)->assertOk()->assertJsonPath('post.status','Published')->assertDontSee('PRIVATE-TOKEN');$this->postJson('/admin/marketing/posts/data/publish',$p)->assertStatus(409);Http::assertSentCount(2);$raw=DB::table('marketing_post_attempts')->value('receipt');$this->assertStringNotContainsString('upload_id=fixture',$raw); }
 public function test_tiktok_requires_manual_privacy_and_terms_before_any_submission(){ $p=$this->fixture('tiktok');unset($p['options'][$p['targets'][0]]['privacy']);$this->postJson('/admin/marketing/posts/data/publish',$p)->assertUnprocessable();Http::assertNothingSent();$p['options'][$p['targets'][0]]['privacy']='SELF_ONLY';$p['options'][$p['targets'][0]]['terms']=false;$this->postJson('/admin/marketing/posts/data/publish',$p)->assertUnprocessable();Http::assertNothingSent(); }
 public function test_tiktok_stores_publish_id_and_uploads_once_then_checks_known_task(){ $p=$this->fixture('tiktok');Http::fake(['*/creator_info/query/'=>Http::response(['data'=>['creator_nickname'=>'Test creator','privacy_level_options'=>['SELF_ONLY'],'comment_disabled'=>true,'duet_disabled'=>true,'stitch_disabled'=>true,'max_video_post_duration_sec'=>60],'error'=>['code'=>'ok']]),'*/video/init/'=>Http::response(['data'=>['publish_id'=>'publish-1','upload_url'=>'https://upload.us.tiktokapis.com/video/?upload_token=PRIVATE-UPLOAD'],'error'=>['code'=>'ok']]),'upload.us.tiktokapis.com/*'=>Http::response('',201),'*/status/fetch/'=>Http::response(['data'=>['status'=>'PUBLISH_COMPLETE','publicaly_available_post_id'=>[]],'error'=>['code'=>'ok']])]);$r=$this->postJson('/admin/marketing/posts/data/publish',$p)->assertOk()->assertJsonPath('post.status','Published')->assertDontSee('PRIVATE-UPLOAD');$this->postJson('/admin/marketing/posts/data/refresh',['id'=>$p['id'],'version'=>$r->json('post.version')])->assertOk();Http::assertSentCount(4); }
 public function test_external_video_gate_and_unsafe_upload_urls_are_blocked(){ $p=$this->fixture();config(['marketing.external_video_publishing_enabled'=>false]);$this->postJson('/admin/marketing/posts/data/publish',$p)->assertStatus(423);Http::assertNothingSent(); }

 public function test_existing_mp4_upload_verifies_duration_and_remains_owned(){
  $this->fixture();$atom=fn($type,$body)=>pack('N',strlen($body)+8).$type.$body;$mvhd=str_repeat("\0",12).pack('NN',1000,15000);$hdlr=str_repeat("\0",8).'vide';$mp4=$atom('ftyp','isom'.str_repeat("\0",4)).$atom('moov',$atom('mvhd',$mvhd).$atom('trak',$atom('mdia',$atom('hdlr',$hdlr))));$r=$this->post('/admin/marketing/posts/upload',['file'=>\Illuminate\Http\UploadedFile::fake()->createWithContent('existing.mp4',$mp4)],['Accept'=>'application/json'])->assertOk()->assertJsonPath('asset.seconds',15);$key=$r->json('asset.id');$this->get('/admin/marketing/posts/media/'.$key)->assertOk();$this->actingAs(User::factory()->create(['is_admin'=>true,'is_super_admin'=>true]));$this->get('/admin/marketing/posts/media/'.$key)->assertNotFound();Http::assertNothingSent();
 }

 public function test_unknown_youtube_upload_queries_the_same_session_without_new_initialization(){
  $p=$this->fixture();$init=0;$puts=0;Http::fake(function($r)use(&$init,&$puts){if($r->method()==='POST'){$init++;return Http::response([],200,['Location'=>'https://www.googleapis.com/upload/youtube/v3/videos?upload_id=known']);}$puts++;if($puts===1)throw new \Illuminate\Http\Client\ConnectionException('test timeout');return Http::response(['id'=>'known-video','status'=>['uploadStatus'=>'processed','privacyStatus'=>'private']]);});$r=$this->postJson('/admin/marketing/posts/data/publish',$p)->assertOk()->assertJsonPath('post.status','Needs attention');$this->postJson('/admin/marketing/posts/data/publish',$p)->assertStatus(409);$this->postJson('/admin/marketing/posts/data/refresh',['id'=>$p['id'],'version'=>$r->json('post.version')])->assertOk()->assertJsonPath('post.status','Published');$this->assertSame(1,$init);$this->assertSame(2,$puts);Http::assertSent(fn($r)=>$r->method()==='PUT'&&$r->hasHeader('Content-Range','bytes */16'));
 }
 public function test_tiktok_disallowed_visibility_stops_before_upload_creation(){
  $p=$this->fixture('tiktok');$p['options'][$p['targets'][0]]['privacy']='PUBLIC_TO_EVERYONE';Http::fake(['*/creator_info/query/'=>Http::response(['data'=>['creator_nickname'=>'Test','privacy_level_options'=>['SELF_ONLY'],'max_video_post_duration_sec'=>60],'error'=>['code'=>'ok']])]);$this->postJson('/admin/marketing/posts/data/publish',$p)->assertUnprocessable();Http::assertSentCount(1);$this->assertDatabaseCount('marketing_post_attempts',0);
 }
 public function test_untrusted_upload_host_is_never_used(){
  $p=$this->fixture();Http::fake(['www.googleapis.com/*'=>Http::response([],200,['Location'=>'https://attacker.invalid/upload'])]);$this->postJson('/admin/marketing/posts/data/publish',$p)->assertOk()->assertJsonPath('post.status','Needs attention');Http::assertSentCount(1);$this->assertStringNotContainsString('attacker.invalid',DB::table('marketing_post_attempts')->value('receipt'));
 }
}
